INSERT INTO releases (version, released_on, title, public_notes, tech_notes) VALUES (
  '2.63.0',
  '2026-08-03',
  'Новая страница «Тесты»: ПДД Армении — 1032 официальных вопроса с картинками',
  E'Появилась страница «Тесты» — подготовка к экзамену по карточкам. Первая колода: официальные экзаменационные вопросы по ПДД Армении (1032 вопроса с картинками, комплект дорожной полиции от 25.12.2025).\n\nКнопка «Продолжить» показывает вперемешку только те вопросы, которые вы ещё не прошли: ответили верно — вопрос уходит из набора, ошиблись — возвращается. Есть «Ошибки» (только те, где ошибались), «Все вопросы», разбор по темам и «Начать сначала» — колода открывается заново, статистика сохраняется.\n\nЭкзамен устроен как настоящий: 20 вопросов за 30 минут, допускаются 2 ошибки, правильные ответы показываются в конце вместе с разбором ошибок. В настройках страницы можно потребовать 2 или 3 верных ответа подряд, чтобы вопрос считался пройденным.',
  E'Миграция 0071: test_decks / test_groups / test_questions (контент, общий) + test_progress / test_sessions / test_session_items (личные) + user_settings.tests_pass_streak. Пул прогона (unpassed | wrong | group | all) выбирается и перемешивается на сервере, порядок фиксируется в test_session_items — перезагрузка не тасует колоду. Статус «пройден» — после N верных подряд (порог из настроек, 1-5), ошибка сбрасывает серию.\n\nПравильный ответ не отдаётся ни в списке, ни в выдаче текущего вопроса — только в ответе на POST /answer и в /review завершённого прогона, иначе учебный режим обходится через девтулзы. Экзамен: параметры в колоде, дедлайн expires_at, вердикт считается при завершении (в т.ч. досрочном и по таймауту).\n\nКолода залита НЕ миграцией, а идемпотентным админским импортом POST /admin/tests/import (multipart deck+images, ключ (slug, num) — переимпорт обновляет тексты, не сбрасывая прогресс). 669 картинок распакованы в DATA_DIR/tests, раздаются из /uploads/tests.\n\nДанные: вопросы взяты из открытого набора, извлечённого из тех же официальных PDF, и СВЕРЕНЫ с первоисточником (roadpolice.am/exam/ru_group_1..10.pdf) скриптом habits/tools/pdd-import/verify.py: PDF свёрстан в две колонки, поэтому страница режется по вертикали и колонки читаются отдельно; решающая проверка — мультимножество правильных ответов на страницу. Результат: 174 страницы без противоречий, 783 вопроса подтверждены дословно, 124 неоднозначны (у картиночных вопросов варианты повторяются слово в слово), 6 проверены глазами по отрисованным страницам. Найден дефект русского PDF: у вопроса 854 при вёрстке потеряна строка четвёртого варианта при ответе «Отв. 4» — восстановлена по английской версии того же документа (заплатка PATCHES с обязательной ссылкой на источник).\n\nПроверки: 12 дымовых сценариев (tools/pdd-import/smoke_test.sh) — пулы, скрытие ответа, переход в «пройден», стабильность порядка, экзамен с таймером и вердиктом, разбор, порог, сброс, картинки, идемпотентность импорта.'
);
-- +goose StatementEnd

